// Bind the socket to the actual Android Network that owns this interface.
// fromFd duplicates the descriptor; closing it never closes the Go socket.
override fun bindInterfaceControl(fd: Int, interfaceName: String?) {
    require(!interfaceName.isNullOrEmpty()) { "android: missing bind interface" }
    val network = Application.connectivity.allNetworks.firstOrNull {
        Application.connectivity.getLinkProperties(it)?.interfaceName == interfaceName
    } ?: error("android: network interface unavailable: $interfaceName")
    ParcelFileDescriptor.fromFd(fd).use { duplicate ->
        network.bindSocket(duplicate.fileDescriptor)
    }
}

