public func bindInterfaceControl(_ fd: Int32, interfaceName: String?) throws {
    guard let interfaceName, !interfaceName.isEmpty else {
        throw NSError(domain: NSPOSIXErrorDomain, code: Int(EINVAL))
    }
    var interfaceIndex = if_nametoindex(interfaceName)
    guard interfaceIndex != 0 else {
        throw NSError(domain: NSPOSIXErrorDomain, code: Int(ENODEV))
    }
    // Determine the real socket family; do not treat a failed bind as success.
    var address = sockaddr_storage()
    var addressLength = socklen_t(MemoryLayout<sockaddr_storage>.size)
    let familyResult = withUnsafeMutablePointer(to: &address) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            getsockname(fd, $0, &addressLength)
        }
    }
    guard familyResult == 0 else {
        throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
    }
    let level: Int32
    let option: Int32
    switch Int32(address.ss_family) {
    case AF_INET: level = IPPROTO_IP; option = IP_BOUND_IF
    case AF_INET6: level = IPPROTO_IPV6; option = IPV6_BOUND_IF
    default: throw NSError(domain: NSPOSIXErrorDomain, code: Int(EAFNOSUPPORT))
    }
    guard setsockopt(fd, level, option, &interfaceIndex, socklen_t(MemoryLayout<UInt32>.size)) == 0 else {
        throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
    }
}

